BEGIN;
SET LOCAL lock_timeout='5s'; SET LOCAL statement_timeout='25s';
DO $policy_sync$
DECLARE ctl jsonb; q population_top3000_202608_202609_v1.continuation_clear_queue_v6%rowtype;
h population_top3000_202608_202609_v1.continuation_handler_v6%rowtype;
before_controls jsonb;after_controls jsonb;before_tasks jsonb;after_tasks jsonb;before_manifest jsonb;
new_bounds jsonb;post_handler jsonb;pol record;review_id bigint;effect_id bigint;used_bytes bigint;review_details jsonb;
BEGIN
ctl:=population_top3000_202608_202609_v1.continuation_guard_v6('top3000-completion-20261024-root-5db48b32d103',3,1);
SELECT * INTO STRICT q FROM population_top3000_202608_202609_v1.continuation_clear_queue_v6 WHERE clearing_id='resource:b8751e6ecb94674efbdf0fa1e4b179d08086dee838ec5a6d6247e8e7645abfb9' FOR UPDATE;
IF q.status IS DISTINCT FROM 'CLAIMED' OR q.input_sha256 IS DISTINCT FROM 'b8751e6ecb94674efbdf0fa1e4b179d08086dee838ec5a6d6247e8e7645abfb9' OR q.claim_expires_at<=clock_timestamp() OR q.claim_token_sha256 IS DISTINCT FROM encode(sha256(convert_to('REPLACE_WITH_EXACT_OWN_CLAIM_TOKEN','UTF8')),'hex') OR q.assignment_event_id<>33158 OR q.assigned_executor IS DISTINCT FROM 'automation:6adc2c96db348191bca7cf4eacfdac32' OR q.not_after<=clock_timestamp() OR q.not_after IS NULL OR q.claim_expires_at IS NULL OR q.family_id IS DISTINCT FROM 'RESOURCE' OR q.kind IS DISTINCT FROM 'OPERATIONAL_REVIEW' OR q.owner_id IS DISTINCT FROM ctl->>'owner_id' OR q.owner_fence::text IS DISTINCT FROM ctl->>'owner_fence' OR q.stop_generation::text IS DISTINCT FROM ctl->>'stop_generation' OR q.scope_sha256 IS DISTINCT FROM ctl->>'scope_sha256' THEN RAISE EXCEPTION 'EXACT_RESOURCE_CLAIM_REQUIRED';END IF;
SELECT * INTO STRICT h FROM population_top3000_202608_202609_v1.continuation_handler_v6 WHERE kind='CTX02_PAGE_ADMISSION' FOR UPDATE;
IF h.enabled IS DISTINCT FROM true OR h.review_event_id IS DISTINCT FROM 28759 OR h.function_sha256 IS DISTINCT FROM '7b68f7313f94151d9c8a5590c2b80a5fd74a6c784e5c9a5f4b6c19ceee38252e' OR h.function_oid IS DISTINCT FROM 'population_top3000_202608_202609_v1.ctx02_clear_page_admission_v6(text,bigint,bigint,jsonb)'::regprocedure OR h.function_sha256 IS DISTINCT FROM encode(sha256(convert_to(pg_get_functiondef(h.function_oid),'UTF8')),'hex') OR encode(sha256(convert_to(h.bounds::text,'UTF8')),'hex') IS DISTINCT FROM 'b38e09dc71a4dcaef996a8b062dee353eae67a44d8f5e13b2362b0857ba09f51' THEN RAISE EXCEPTION 'EXACT_POLICY_PREIMAGE_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pc WHERE a.singleton AND pc.singleton AND a.max_source_bytes=1000000000 AND a.max_provider_requests=10000 AND a.max_http_invocations=10055 AND pc.max_ticks=26000 AND pc.budget_evidence#>>'{resource_limits,max_relation_bytes}'='12000000000' AND pc.deadline='2026-10-25T22:36:17.687194Z'::timestamptz) THEN RAISE EXCEPTION 'EXACT_ADMITTED_GLOBAL_CAPS_REQUIRED';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event WHERE event_id=32258 AND event='CONTINUATION_MEASURED_ADMISSION_V6' AND details#>>'{proposal,new_max_relation_bytes}'='12000000000' AND details->>'cumulative_counters_preserved'='true' AND details->>'original_deadline_preserved'='true') THEN RAISE EXCEPTION 'PRIOR_MEASURED_ADMISSION_REQUIRED';END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE family_id='CTX02' AND status='LEASED') OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_provider_lease WHERE released_at IS NULL) OR EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.connector_probe_lease_v1 WHERE released_at IS NULL) THEN RAISE EXCEPTION 'ACTIVE_AFFECTED_WORK_RETRY_LATER';END IF;
SELECT jsonb_build_object('acquisition',to_jsonb(a),'pipeline',to_jsonb(pc)) INTO before_controls FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pc WHERE a.singleton AND pc.singleton;
SELECT jsonb_agg(to_jsonb(t) ORDER BY task_id) INTO before_tasks FROM population_top3000_202608_202609_v1.pipeline_task t WHERE h.bounds->'request_policies' ? t.task_id::text;
IF jsonb_array_length(before_tasks) IS DISTINCT FROM 3 THEN RAISE EXCEPTION 'THREE_PINNED_REQUESTS_REQUIRED';END IF;
FOR pol IN SELECT t.task_id,t.payload,t.input_versions,h.bounds->'request_policies'->t.task_id::text binding FROM population_top3000_202608_202609_v1.pipeline_task t WHERE h.bounds->'request_policies' ? t.task_id::text LOOP
IF encode(sha256(convert_to(pol.payload::text,'UTF8')),'hex') IS DISTINCT FROM pol.binding->>'payload_sha256' OR encode(sha256(convert_to(pol.input_versions::text,'UTF8')),'hex') IS DISTINCT FROM pol.binding->>'input_versions_sha256' OR pol.payload->>'request_key' IS DISTINCT FROM pol.binding->>'request_key' THEN RAISE EXCEPTION 'REQUEST_POLICY_PREIMAGE_CHANGED';END IF;
END LOOP;
before_manifest:=population_top3000_202608_202609_v1.population_recovery_manifest_v1();
new_bounds:=jsonb_set(h.bounds,'{global_ceiling,relation_bytes}','12000000000'::jsonb);
IF encode(sha256(convert_to(new_bounds::text,'UTF8')),'hex') IS DISTINCT FROM 'a1dba514a1fd4550b4bc44433046e8c730ac19861e5e1b2d19615c15f410de21' OR (new_bounds#-'{global_ceiling,relation_bytes}') IS DISTINCT FROM (h.bounds#-'{global_ceiling,relation_bytes}') THEN RAISE EXCEPTION 'ONLY_REVIEWED_RELATION_POLICY_DIFF_ALLOWED';END IF;
IF EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event e WHERE e.event_id=h.review_event_id AND e.details->>'handler_bounds_sha256'=encode(sha256(convert_to(new_bounds::text,'UTF8')),'hex')) THEN RAISE EXCEPTION 'OLD_REVIEW_MUST_REJECT_NEW_BOUNDS';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_task WHERE task_id='da79b746-8550-41c9-a6f0-3d87f4e352fd' AND status IN('READY','BLOCKED')) THEN RAISE EXCEPTION 'EXACT_CONTINUING_TASK_REQUIRED';END IF;
SELECT coalesce(sum(pg_total_relation_size(c.oid)),0) INTO used_bytes FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='population_top3000_202608_202609_v1' AND c.relkind IN('r','m');
IF used_bytes>=12000000000 THEN RAISE EXCEPTION 'LIVE_RELATION_CAP_REACHED';END IF;
review_details:=ctl||jsonb_build_object('approved',true,'producer','automation:6adc2c96db348191bca7cf4eacfdac32','reviewer','/root/verify_daily_dependency','clearing_id',q.clearing_id,'input_sha256',q.input_sha256,'claim_event_id',33288,'handler_function_sha256',h.function_sha256,'handler_bounds_sha256','a1dba514a1fd4550b4bc44433046e8c730ac19861e5e1b2d19615c15f410de21','prior_handler_bounds_sha256','b38e09dc71a4dcaef996a8b062dee353eae67a44d8f5e13b2362b0857ba09f51','prior_review_event_id',h.review_event_id,'bounds',new_bounds,'approval_scope','EXACT_POLICY_DATA_SYNC_TO_ALREADY_MEASURED_ADMISSION_32258','source_provider_http_tick_limits_unchanged',true,'no_new_capacity_admitted',true);
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details) VALUES('OPTIONS_POLICY_MEASURED_SYNC_INDEPENDENT_REVIEW_V1',review_details) RETURNING event_id INTO review_id;
UPDATE population_top3000_202608_202609_v1.continuation_handler_v6 SET bounds=new_bounds,review_event_id=review_id WHERE kind=h.kind;
SELECT to_jsonb(ch) INTO post_handler FROM population_top3000_202608_202609_v1.continuation_handler_v6 ch WHERE kind=h.kind;
IF post_handler->'bounds' IS DISTINCT FROM new_bounds OR post_handler->>'review_event_id' IS DISTINCT FROM review_id::text THEN RAISE EXCEPTION 'POLICY_UPDATE_READBACK_FAILED';END IF;
IF (post_handler-ARRAY['bounds','review_event_id']) IS DISTINCT FROM (to_jsonb(h)-ARRAY['bounds','review_event_id']) THEN RAISE EXCEPTION 'HANDLER_COLLATERAL_CHANGE';END IF;
IF NOT EXISTS(SELECT 1 FROM population_top3000_202608_202609_v1.pipeline_event e WHERE e.event_id=review_id AND e.details->>'approved'='true' AND e.details->>'handler_function_sha256'=h.function_sha256 AND e.details->>'handler_bounds_sha256'=encode(sha256(convert_to(new_bounds::text,'UTF8')),'hex') AND e.details->>'owner_id'=ctl->>'owner_id' AND e.details->>'owner_fence'=ctl->>'owner_fence' AND e.details->>'stop_generation'=ctl->>'stop_generation' AND e.details->>'scope_sha256'=ctl->>'scope_sha256' AND nullif(e.details->>'producer','') IS NOT NULL AND nullif(e.details->>'reviewer','') IS NOT NULL AND e.details->>'producer' IS DISTINCT FROM e.details->>'reviewer') THEN RAISE EXCEPTION 'EXACT_INSTALLED_HELPER_REVIEW_PREDICATE_FAILED';END IF;
IF least((new_bounds#>>'{global_ceiling,relation_bytes}')::bigint,(before_controls#>>'{pipeline,budget_evidence,resource_limits,max_relation_bytes}')::bigint)<>12000000000 THEN RAISE EXCEPTION 'EFFECTIVE_RELATION_CAP_WRONG';END IF;
SELECT jsonb_build_object('acquisition',to_jsonb(a),'pipeline',to_jsonb(pc)) INTO after_controls FROM population_top3000_202608_202609_v1.acquisition_control a CROSS JOIN population_top3000_202608_202609_v1.pipeline_control pc WHERE a.singleton AND pc.singleton;
SELECT jsonb_agg(to_jsonb(t) ORDER BY task_id) INTO after_tasks FROM population_top3000_202608_202609_v1.pipeline_task t WHERE h.bounds->'request_policies' ? t.task_id::text;
IF before_controls IS DISTINCT FROM after_controls OR before_tasks IS DISTINCT FROM after_tasks OR before_manifest IS DISTINCT FROM population_top3000_202608_202609_v1.population_recovery_manifest_v1() THEN RAISE EXCEPTION 'CONTROL_TASK_OR_CODE_MANIFEST_CHANGED';END IF;
INSERT INTO population_top3000_202608_202609_v1.pipeline_event(event,details)
VALUES('CONTINUATION_MEASURED_ADMISSION_V6',ctl||jsonb_build_object('admission_class','POLICY_ONLY_SYNC_TO_EXISTING_MEASURED_ADMISSION_32258','clearing_id',q.clearing_id,'input_sha256',q.input_sha256,'claim_event_id',33288,'independent_review_event_id',review_id,'effects_known',true,'cumulative_counters_preserved',true,'original_deadline_preserved',true,'source_holds_unchanged',true,'mission_relation_bytes',used_bytes,'old_policy_relation_bytes',8000000000,'new_policy_relation_bytes',12000000000,'policy_sha256','a1dba514a1fd4550b4bc44433046e8c730ac19861e5e1b2d19615c15f410de21','new_capacity_admitted',false,'source_api_calls_performed',0,'source_provider_http_tick_limits_unchanged',true,'recovery_manifest_unchanged',true,'original_tasks_unchanged',true,'successor_task_id','da79b746-8550-41c9-a6f0-3d87f4e352fd','data_acceptance',false)) RETURNING event_id INTO effect_id;
END $policy_sync$;
-- Append COMMIT only after exact claim substitution and independent rollback review.
